// Accepts either a W2 buy_intent item or a raw message, and decides with BOTH signals:
// the classifier's buy_intent OR a literal trigger word. Two independent paths to the
// same row, because the classifier can be wrong and 'אני רוצה' cannot.
const TRIGGERS = ['אני רוצה', 'רוצה את', 'רוצה', 'לקנות', 'איך מזמינים', 'i want', 'want it', 'buy', 'how do i order', 'order'];
const j = $input.first().json.body || $input.first().json;
const text = String(j.text || '').toLowerCase();
const hit = TRIGGERS.some(t => text.includes(t.toLowerCase()));
if (j.priority !== 'buy_intent' && !hit) return [];
return [{ json: {
  ts: new Date().toISOString(),
  platform: j.platform || 'youtube',
  name: j.name || 'viewer',
  handle: j.handle || '',
  product: j.product || '',
  message: j.text || '',
}}];
